from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM market research workspace"], include_in_schema=False)
_HEADERS = {"Cache-Control":"no-store","Content-Security-Policy":"default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff"}
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تحقیق و شناخت بازار | فانل CRM</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px 1fr}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:bold;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.top,.filters{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.top{margin-bottom:20px}.field{display:grid;gap:6px;font-size:11px;color:#778697}select,input{font:inherit;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:160px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0 0 15px}.status{min-height:20px;color:#718092;font-size:12px}.error{color:#a74137}.notice{background:#eef6f8;border:1px solid #d8e9ed;border-right:3px solid #19838d;padding:12px 15px;border-radius:10px;color:#3f6672;font-size:11px;line-height:1.9;margin:12px 0}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408;min-width:0}.label{color:#657487;font-size:11px}.value{font-size:22px;font-weight:bold;color:#1a334c;margin:9px 0 3px}.meta{font-size:10px;color:#8290a0;line-height:1.7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 0 12px}.heading h2{font-size:15px;margin:0}.form{display:grid;gap:10px}.row{display:grid;grid-template-columns:1fr 1fr;gap:9px}button{font:inherit;cursor:pointer;border-radius:8px;padding:9px 12px;font-size:11px}.primary{border:0;background:#126b91;color:white}.secondary{border:1px solid #d8e2ea;background:white;color:#31536c}.list{display:grid;gap:8px}.item{border:1px solid #e8edf2;border-radius:9px;padding:11px;font-size:11px;line-height:1.8}.item strong{display:block;color:#304b60}.pill{display:inline-block;border-radius:99px;background:#eff4f7;color:#506879;padding:3px 8px;font-size:10px}.bars{display:grid;gap:10px}.barrow{display:grid;grid-template-columns:110px 1fr 65px;gap:8px;align-items:center;font-size:11px}.track{height:9px;background:#edf2f6;border-radius:9px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#24b5a5,#17658e)}.empty{font-size:11px;line-height:1.8;color:#7b8998;text-align:center;padding:14px;border:1px dashed #d4dde6;border-radius:9px}.foot{color:#8995a1;font-size:10px;line-height:1.8;margin-top:13px}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:8px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.main{padding:15px 12px}.top,.filters{display:grid}.field,select,input{width:100%;min-width:0}.row{grid-template-columns:1fr}.kpis{gap:7px}.card{padding:12px}.value{font-size:18px}}</style><script src="/assets/crm-market-research.js" defer></script></head><body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav active" href="/workspace/crm-market-research" aria-current="page">تحقیق و شناخت بازار</a><a class="nav" href="/workspace/crm-campaigns">کمپین و محتوا</a><a class="nav" href="/workspace/crm-customers">مشتریان</a><a class="nav" href="/workspace/crm-analytics">تحلیل و هوش تجاری</a></nav></aside><main class="main"><div class="top"><label class="field">فضای کاری<select id="workspace"><option value="">در حال دریافت…</option></select></label><label class="field">واحد سازمانی<select id="unit"><option value="">در حال دریافت…</option></select></label></div><h1>تحقیق و شناخت بازار</h1><p class="sub">رفتار ثبت‌شدهٔ مشتریان را بخوانید، گروه‌های مخاطب بسازید و اندازهٔ واقعی هر گروه را پیش از برنامه‌ریزی بررسی کنید.</p><div class="notice">این صفحه از داده‌های CRM استفاده می‌کند؛ شمارش تعامل، به‌تنهایی نشان‌دهندهٔ اندازهٔ کل بازار یا علت خرید نیست.</div><p id="status" class="status" role="status" aria-live="polite"></p><section class="kpis"><article class="card"><div class="label">تعامل‌های ۳۰ روز اخیر</div><div id="activity-count" class="value">—</div><div id="activity-change" class="meta">در انتظار داده</div></article><article class="card"><div class="label">مشتریان فعال در تعامل</div><div id="active-profiles" class="value">—</div><div class="meta">پروفایل یکتا با فعالیت ثبت‌شده</div></article><article class="card"><div class="label">گروه‌های مخاطب ذخیره‌شده</div><div id="segment-count" class="value">—</div><div class="meta">در واحد انتخاب‌شده</div></article><article class="card"><div class="label">کانال پرتکرار</div><div id="top-channel" class="value">—</div><div class="meta">بر اساس تعامل‌های ثبت‌شده</div></article></section><div class="grid"><section class="card"><div class="heading"><h2>رفتار ثبت‌شده در کانال‌ها</h2></div><div id="channels" class="bars"><div class="empty">در حال دریافت…</div></div><div class="heading" style="margin-top:18px"><h2>نوع تعامل مشتری</h2></div><div id="types" class="bars"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>ساخت گروه مخاطب</h2></div><form id="segment-form" class="form"><label class="field">نام گروه<input id="segment-name" maxlength="160" required placeholder="مثلاً مشتریان سازمانیِ فعال"></label><div class="row"><label class="field">نوع پروفایل<select id="profile-kind"><option value="person">شخص</option><option value="organization">سازمان</option></select></label><label class="field">مرحلهٔ چرخه عمر<input id="stage" maxlength="80" placeholder="اختیاری؛ مانند lead"></label></div><label class="field">نوع تعامل (اختیاری)<input id="activity-type" maxlength="80" placeholder="کلید انگلیسی؛ مانند visit"></label><label class="field">کانال تعامل<select id="activity-channel"><option value="">همهٔ کانال‌ها</option><option value="online">آنلاین</option><option value="phone">تلفن</option><option value="store">فروشگاه</option><option value="field">میدانی</option><option value="support">پشتیبانی</option><option value="campaign">کمپین</option><option value="other">سایر</option></select></label><label class="field">فعالیت در چند روز اخیر (اختیاری)<input id="activity-days" inputmode="numeric" maxlength="4" placeholder="۱ تا ۳۶۵۰ روز"></label><button id="segment-save" class="primary" type="submit">ذخیرهٔ گروه مخاطب</button></form><p class="meta">فیلترهای انتخاب‌شده هم‌زمان اعمال می‌شوند؛ مشتری باید حداقل یک تعامل مطابق نوع، کانال و بازهٔ تعیین‌شده داشته باشد. خالی‌گذاشتن هر فیلتر یعنی بدون محدودیت در همان معیار.</p></section><section class="card"><div class="heading"><h2>گروه‌های ذخیره‌شده</h2><button id="refresh" class="secondary" type="button">به‌روزرسانی</button></div><div id="segments" class="list"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>پیش‌نمایش اندازهٔ گروه</h2><span id="preview-meta" class="meta">یک گروه را انتخاب کنید</span></div><div id="preview" class="list"><div class="empty">برای مشاهدهٔ شمار و نمونهٔ اعضا، پیش‌نمایش گروه را بزنید.</div></div></section></div><section class="card"><h2>مخاطبان مجاز برای ارتباط</h2><form id="reach-form" class="filters"><label class="field">گروه مخاطب<select id="reach-segment" required></select></label><label class="field">کلید هدف<input id="reach-purpose" maxlength="80" required placeholder="مثلاً marketing"></label><label class="field">کانال<select id="reach-channel"><option value="email">ایمیل</option><option value="phone">تلفن</option><option value="postal_address">نشانی</option><option value="social_handle">شبکهٔ اجتماعی</option><option value="website">وب‌سایت</option></select></label><button id="reach-submit" class="primary" type="submit">سنجش مخاطبان قابل تماس</button></form><div id="reach-result" class="list" role="status" aria-live="polite"></div><p class="meta">این سنجش پیام ارسال نمی‌کند. مجازبودن نیازمند راه تماس تأییدشده و آخرین رضایت صریح برای همین هدف است؛ پیش از ارسال باید دوباره بررسی شود.</p></section><p class="foot">پیش‌نمایش گروه، دادهٔ زندهٔ افراد مجاز را با کنترل دسترسی سمت سرور نشان می‌دهد. برای استفادهٔ کانالی، رضایت و قابلیت تماس باید جداگانه بررسی شوند.</p></main></div></body></html>"""
_SCRIPT = """(()=>{
const $=id=>document.getElementById(id),ws=$("workspace"),unit=$("unit"),fmt=new Intl.NumberFormat("fa-IR");let segments=[],loadGeneration=0,reachGeneration=0,previewGeneration=0;
function say(s,e=false){$("status").textContent=s;$("status").classList.toggle("error",e)}function el(t,v,c=""){const n=document.createElement(t);n.textContent=String(v??"—");if(c)n.className=c;return n}
async function api(p,o={}){const h={Accept:"application/json","X-Workspace-ID":ws.value,...(o.headers||{})};if(o.body)h["Content-Type"]="application/json";const r=await fetch(p,{...o,credentials:"same-origin",headers:h});if(r.status===204)return null;let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw Error(typeof d.detail==="string"?d.detail:"درخواست ناموفق بود");return d}
function bars(id,rows){const box=$(id);box.replaceChildren();if(!rows?.length){box.append(el("div","در این دوره داده‌ای ثبت نشده است.","empty"));return}const max=Math.max(1,...rows.map(x=>x.current_count));for(const x of rows){const row=document.createElement("div");row.className="barrow";row.append(el("span",x.key));const track=document.createElement("div");track.className="track";const fill=document.createElement("div");fill.className="fill";fill.style.width=Math.max(2,100*x.current_count/max)+"%";track.append(fill);row.append(track,el("span",fmt.format(x.current_count)+" · قبل "+fmt.format(x.previous_count)));box.append(row)}}
function clearReach(){reachGeneration++;$("reach-result").replaceChildren();$("reach-submit").disabled=false}
async function reviewReach(){const box=$("reach-result"),button=$("reach-submit"),scope=ws.value+":"+unit.value,id=$("reach-segment").value,purpose=$("reach-purpose").value.trim(),channel=$("reach-channel").value;if(button.disabled||!ws.value||!unit.value)return;clearReach();if(!segments.some(x=>x.id===id&&x.is_active&&x.organization_unit_id===unit.value)||!/^[a-z][a-z0-9_.-]{0,79}$/.test(purpose)){box.append(el("p","گروه و کلید هدف معتبر را انتخاب کنید."));return}const generation=++reachGeneration;button.disabled=true;
try{const d=await api("/api/v1/crm/segments/"+encodeURIComponent(id)+"/reach?"+new URLSearchParams({purpose_key:purpose,channel}));if(generation!==reachGeneration||scope!==ws.value+":"+unit.value)return;for(const [key,label] of [["total_profiles","کل اعضای گروه"],["profiles_with_contact","دارای راه تماس"],["profiles_with_verified_contact","دارای راه تماس تأییدشده"],["profiles_with_granted_consent","دارای رضایت معتبر"],["eligible_profiles","مجاز برای ارتباط"],["withdrawn_consent_profiles","رضایت لغوشده"],["missing_or_withdrawn_consent_profiles","بدون رضایت معتبر"]])box.append(el("div",label+": "+fmt.format(d[key]),"item"))}catch(error){if(generation===reachGeneration&&scope===ws.value+":"+unit.value)box.append(el("p","سنجش انجام نشد: "+error.message))}finally{if(generation===reachGeneration)button.disabled=false}}
$("reach-form").addEventListener("submit",event=>{event.preventDefault();reviewReach()});for(const id of ["reach-segment","reach-purpose","reach-channel"])$(id).addEventListener("change",clearReach);
function clearPreview(){previewGeneration++;$("preview").replaceChildren();$("preview-meta").textContent="یک گروه را انتخاب کنید"}
async function preview(id){const selected=segments.find(x=>x.id===id&&x.organization_unit_id===unit.value&&x.is_active);if(!selected)return;clearPreview();const generation=++previewGeneration,scope=ws.value+":"+unit.value,box=$("preview"),rows=document.createElement("div"),message=el("p","در حال دریافت اعضا…"),button=el("button","نمایش اعضای بیشتر","secondary");button.type="button";message.setAttribute("role","status");box.append(message,rows,button);let offset=0,busy=false;const seen=new Set();
const current=()=>generation===previewGeneration&&scope===ws.value+":"+unit.value;
async function next(){if(busy||!current())return;busy=true;button.disabled=true;try{const d=await api("/api/v1/crm/segments/"+encodeURIComponent(id)+"/preview?"+new URLSearchParams({limit:"50",offset:String(offset)}));if(!current())return;for(const x of d.items){if(seen.has(x.id))continue;seen.add(x.id);const item=document.createElement("article");item.className="item";item.append(el("strong",x.display_name),el("span",(x.profile_kind==="person"?"شخص":"سازمان")+" · "+x.lifecycle_stage,"pill"));rows.append(item)}offset+=d.items.length;$("preview-meta").textContent=selected.name+" · تعداد کل: "+fmt.format(d.total);message.textContent=d.total?"نمایش "+fmt.format(seen.size)+" از "+fmt.format(d.total)+" عضو":"عضوی با معیارهای فعلی پیدا نشد.";button.hidden=offset>=d.total||!d.items.length;button.textContent="نمایش اعضای بیشتر"}catch(error){if(current()){message.textContent="دریافت اعضا انجام نشد: "+error.message;button.hidden=false;button.textContent="تلاش دوباره"}}finally{busy=false;if(current())button.disabled=false}}
button.addEventListener("click",next);await next();return next}

function drawSegments(){const select=$("reach-segment");select.replaceChildren(el("option","انتخاب کنید"));select.children[0].value="";for(const x of segments.filter(x=>x.is_active&&x.organization_unit_id===unit.value)){const option=el("option",x.name);option.value=x.id;select.append(option)}const box=$("segments");box.replaceChildren();if(!segments.length){box.append(el("div","گروه فعالی در این واحد ثبت نشده است.","empty"));return}for(const x of segments){const item=document.createElement("article");item.className="item";item.append(el("strong",x.name),el("span",x.criteria.profile_kinds?.join(", ")||"همهٔ انواع","pill"));if(x.criteria.lifecycle_stages)item.append(el("div","مرحله: "+x.criteria.lifecycle_stages.join("، ")));if(x.criteria.activity){const a=x.criteria.activity;if(a.activity_types)item.append(el("div","تعامل: "+a.activity_types.join("، ")));if(a.channels)item.append(el("div","کانال تعامل: "+a.channels.join("، ")));if(a.within_last_days)item.append(el("div","در "+fmt.format(a.within_last_days)+" روز اخیر"))}const b=document.createElement("button");b.className="secondary";b.type="button";b.textContent="پیش‌نمایش اعضا";b.addEventListener("click",()=>preview(x.id));item.append(b);box.append(item)}}
async function load(){clearPreview();clearReach();const generation=++loadGeneration,scope=ws.value+":"+unit.value;if(!ws.value||!unit.value)return;say("در حال خواندن تحلیل و گروه‌های مخاطب…");const id=encodeURIComponent(unit.value);const results=await Promise.allSettled([api("/api/v1/crm/analytics/customer-activities/summary?window_days=30&organization_unit_id="+id),api("/api/v1/crm/segments?organization_unit_id="+id+"&limit=100")]);if(generation!==loadGeneration||scope!==ws.value+":"+unit.value)return;const [a,s]=results;if(a.status==="fulfilled"){const d=a.value;$("activity-count").textContent=fmt.format(d.current_activity_count);$("active-profiles").textContent=fmt.format(d.current_profiles_with_activity);$("activity-change").textContent=d.activity_count_change_percent==null?"تغییر دوره‌ای قابل محاسبه نیست":fmt.format(d.activity_count_change_percent)+"٪ نسبت به دورهٔ قبل";$("top-channel").textContent=d.by_channel[0]?.key||"—";bars("channels",d.by_channel);bars("types",d.by_activity_type)}else{say("تحلیل تعاملات در دسترس نیست: "+a.reason.message,true)}segments=s.status==="fulfilled"?s.value.items:[];$("segment-count").textContent=fmt.format(s.status==="fulfilled"?s.value.total:0);drawSegments();if(s.status==="rejected")say("تحلیل یا فهرست گروه‌ها در دسترس نیست: "+s.reason.message,true);else if(a.status==="fulfilled")say("تحلیل رفتار و گروه‌های مخاطب به‌روز شد.")}
function segmentCriteria(){const criteria={profile_kinds:[$("profile-kind").value]},stage=$("stage").value.trim(),type=$("activity-type").value.trim(),channel=$("activity-channel").value,raw=$("activity-days").value.trim(),activity={};if(stage)criteria.lifecycle_stages=[stage];if(type){if(!/^[a-z][a-z0-9_.-]{0,79}$/.test(type))throw Error("نوع تعامل باید کلید انگلیسی معتبر باشد.");activity.activity_types=[type]}if(channel){if(!["online","phone","store","field","support","campaign","other"].includes(channel))throw Error("کانال تعامل معتبر نیست.");activity.channels=[channel]}if(raw){const normalized=Array.from(raw,c=>"۰۱۲۳۴۵۶۷۸۹".includes(c)?String("۰۱۲۳۴۵۶۷۸۹".indexOf(c)):"٠١٢٣٤٥٦٧٨٩".includes(c)?String("٠١٢٣٤٥٦٧٨٩".indexOf(c)):c).join("");if(!/^[0-9]+$/.test(normalized)||Number(normalized)<1||Number(normalized)>3650)throw Error("بازهٔ فعالیت باید عدد صحیح بین ۱ تا ۳۶۵۰ روز باشد.");activity.within_last_days=Number(normalized)}if(Object.keys(activity).length)criteria.activity=activity;return criteria}
async function saveSegment(){const button=$("segment-save"),scope=ws.value+":"+unit.value;if(button.disabled||!ws.value||!unit.value)return;let criteria;try{criteria=segmentCriteria()}catch(error){say(error.message,true);return}const name=$("segment-name").value.trim();if(!name){say("نام گروه را وارد کنید.",true);return}button.disabled=true;ws.disabled=true;unit.disabled=true;try{await api("/api/v1/crm/segments",{method:"POST",body:JSON.stringify({organization_unit_id:unit.value,name,criteria})});if(scope!==ws.value+":"+unit.value)return;say("گروه مخاطب ذخیره شد.");await load()}catch(error){if(scope===ws.value+":"+unit.value)say("ذخیرهٔ گروه انجام نشد: "+error.message,true)}finally{button.disabled=false;ws.disabled=false;unit.disabled=false}}
$("segment-form").addEventListener("submit",event=>{event.preventDefault();saveSegment()});

async function init(){clearPreview();clearReach();loadGeneration++;const selected=ws.value;try{const w=await api("/api/v1/system/workspaces");ws.replaceChildren(...w.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!w.length)throw Error("فضای کاری یافت نشد");ws.value=w.some(x=>x.id===selected)?selected:w[0].id;const u=await api("/api/v1/system/organization-units");unit.replaceChildren(...u.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!u.length)throw Error("واحد سازمانی مجاز یافت نشد");unit.value=u[0].id;await load()}catch(e){say("داده‌ها بارگذاری نشد: "+e.message,true)}}
$("refresh").addEventListener("click",load);unit.addEventListener("change",load);ws.addEventListener("change",init);init();
})();"""
@router.get("/workspace/crm-market-research", response_class=HTMLResponse)
async def market_research_workspace() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-market-research.js")
async def market_research_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers=_HEADERS)
